// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/readyz", wrapper.Ready)
	m.HandleFunc("GET "+options.BaseURL+"/v1/asset-groups", wrapper.ListAssetGroups)
	m.HandleFunc("POST "+options.BaseURL+"/v1/asset-groups", wrapper.CreateAssetGroup)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/asset-groups/{groupId}", wrapper.DeleteAssetGroup)
	m.HandleFunc("POST "+options.BaseURL+"/v1/asset-imports", wrapper.ImportAsset)
	m.HandleFunc("GET "+options.BaseURL+"/v1/assets", wrapper.ListAssets)
	m.HandleFunc("GET "+options.BaseURL+"/v1/assets/unused", wrapper.ListUnusedAssets)
	m.HandleFunc("GET "+options.BaseURL+"/v1/assets/{assetId}", wrapper.ReadAsset)
	m.HandleFunc("GET "+options.BaseURL+"/v1/assets/{assetId}/bytes", wrapper.ReadAssetBytes)
	m.HandleFunc("HEAD "+options.BaseURL+"/v1/assets/{assetId}/bytes", wrapper.HeadAssetBytes)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/assets/{assetId}/group", wrapper.SetAssetGroup)
	m.HandleFunc("GET "+options.BaseURL+"/v1/assets/{assetId}/references", wrapper.ReadAssetReferences)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/assets/{assetId}/variants", wrapper.AttachImageVariants)
	m.HandleFunc("GET "+options.BaseURL+"/v1/cleanup-plans", wrapper.ListCleanupPlans)
	m.HandleFunc("POST "+options.BaseURL+"/v1/cleanup-plans", wrapper.ProposeManualCleanup)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/cleanup-plans/{planId}", wrapper.CancelManualCleanup)
	m.HandleFunc("POST "+options.BaseURL+"/v1/cleanup-plans/{planId}:confirm", wrapper.ConfirmManualCleanup)
	m.HandleFunc("POST "+options.BaseURL+"/v1/delivery-manifests", wrapper.BuildDeliveryManifest)
	m.HandleFunc("POST "+options.BaseURL+"/v1/jobs/{jobId}/recovery", wrapper.ReadJobRecovery)
	m.HandleFunc("POST "+options.BaseURL+"/v1/references:acquire", wrapper.AcquireResourceReferences)
	m.HandleFunc("POST "+options.BaseURL+"/v1/references:confirm", wrapper.ConfirmResourceReferences)
	m.HandleFunc("POST "+options.BaseURL+"/v1/references:release", wrapper.ReleaseResourceReferences)
	m.HandleFunc("POST "+options.BaseURL+"/v1/uploads", wrapper.BeginUpload)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/uploads/{uploadId}", wrapper.AbortUpload)
	m.HandleFunc("GET "+options.BaseURL+"/v1/uploads/{uploadId}", wrapper.ReadUpload)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/uploads/{uploadId}/chunks", wrapper.PutUploadChunk)
	m.HandleFunc("POST "+options.BaseURL+"/v1/uploads/{uploadId}:complete", wrapper.CompleteUpload)
	m.HandleFunc("POST "+options.BaseURL+"/v1/videos/metadata", wrapper.ReadVideoMetadata)

	return m
}

